    search_tsv tsvector GENERATED ALWAYS AS (to_tsvector('simple', coalesce(name, '') || ' ' || coalesce(description, ''))) STORED
);
create index idx_projects_visibility on projects (visibility);
create unique index uniq_projects_slug on projects (slug);

create table reputation_events (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    project_id bigint NOT NULL,
    user_id bigint NOT NULL,
    kind text NOT NULL,
    points double precision NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);
create index idx_rep on reputation_events (project_id, user_id);

create table request_answer_votes (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    request_id bigint NOT NULL,
    answer_a bigint NOT NULL,
    answer_b bigint NOT NULL,
    voter_id bigint NOT NULL,
    outcome text NOT NULL,
    weight double precision DEFAULT 1.0 NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);
create index idx_request_votes on request_answer_votes (request_id, voter_id);
create unique index uniq_request_answer_votes_voter_id_answer_a_answer_b on request_answer_votes (voter_id, answer_a, answer_b);

create table request_answers (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    request_id bigint NOT NULL,
    project_id bigint NOT NULL,
    body text DEFAULT '',
    status text DEFAULT 'active' NOT NULL,
    elo_r double precision DEFAULT 1500 NOT NULL,
    elo_rd double precision DEFAULT 350 NOT NULL,
    elo_vol double precision DEFAULT 0.06 NOT NULL,
    proposed_by bigint NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
create index idx_answers_request on request_answers (request_id, status);
create unique index uniq_request_answers_request_id_project_id on request_answers (request_id, project_id);

create table request_tags (
    request_id bigint NOT NULL,
    tag_id bigint NOT NULL,
    PRIMARY KEY (request_id, tag_id)
);

create table requests (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    project_id bigint,
    author_id bigint NOT NULL,
    title text NOT NULL,
    body text DEFAULT '',
    status text DEFAULT 'open' NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    accepted_answer_id bigint
);
create index idx_requests_status on requests (status, created_at);

create table schema_migrations (
    version bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    applied_at timestamptz NOT NULL
);

create table solution_coverage (
    solution_id bigint NOT NULL,
    complaint_id bigint NOT NULL,
    claim text NOT NULL,
    contested bigint DEFAULT 0 NOT NULL,
    contested_by bigint,
    contested_at timestamptz,
    contest_reason text,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (solution_id, complaint_id)
);
create index idx_coverage_complaint on solution_coverage (complaint_id);

create table solutions (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    feature_id bigint NOT NULL,
    author_id bigint NOT NULL,
    title text NOT NULL,
    body text DEFAULT '' NOT NULL,
    type text NOT NULL,
    external_ref text,
    affiliation text,
    relationship text DEFAULT 'exclusive' NOT NULL,
    parent_solution_id bigint,
    status text DEFAULT 'draft' NOT NULL,
    expertise_tags text DEFAULT '' NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
create unique index idx_solutions_title on solutions (feature_id, title);
create index idx_solutions_feature on solutions (feature_id, status);

